   timeFormat = c.TimeFormat
  }

  switch c.Encoding {
  case plainEncoding:
   atomic.StoreUint32(&encoding, plainEncodingType)
  default:
   atomic.StoreUint32(&encoding, jsonEncodingType)
  }

  switch c.Mode {
  case fileMode:
   err = setupWithFiles(c)
  case volumeMode:
   err = setupWithVolume(c)
  default:
   setupWithConsole()
  }
 })

 return
}

