 "context"
 "github.com/zeromicro/go-zero/core/logx"
)

var globalFields struct {
 sync.RWMutex
 fields []LogField
}

func AddGlobalFields(fields ...LogField) {
 globalFields.Lock()
 globalFields.fields = append(globalFields.fields, fields...)
 globalFields.Unlock()
}

func globalFieldsSnapshot() []LogField {
 globalFields.RLock()
 defer globalFields.RUnlock()
 return append([]LogField(nil), globalFields.fields...)
}

func addCaller(fields ...LogField) []LogField {
 fields = append(globalFieldsSnapshot(), fields...)
 return append(fields, Field(callerKey, getCaller(callerDepth)))
}

func (l *richLogger) buildFields(fields ...LogField) []LogField {
 fields = append(globalFieldsSnapshot(), l.fields...)
 fields = append(fields, fields...)
 fields = append(fields, Field(callerKey, getCaller(callerDepth+l.callerSkip)))

 if l.ctx == nil {
  return fields
 }

 traceID := traceIdFromContext(l.ctx)
 if len(traceID) > 0 {
  fields = append(fields, Field(traceKey, traceID))
 }

 spanID := spanIdFromContext(l.ctx)
 if len(spanID) > 0 {
  fields = append(fields, Field(spanKey, spanID))
 }

 val := l.ctx.Value(fieldsContextKey)
 if val != nil {
  if arr, ok := val.([]LogField); ok {
   fields = append(fields, arr...)
  }
 }

 return fields
}

func (l *richLogger) buildFields(fields ...LogField) []LogField {
 logFields := append(globalFieldsSnapshot(), l.fields...)
 logFields = append(logFields, fields...)
 logFields = append(logFields, Field(callerKey, getCaller(callerDepth+l.callerSkip)))

 if l.ctx == nil {
  return logFields
 }

 traceID := traceIdFromContext(l.ctx)
 if len(traceID) > 0 {
  logFields = append(logFields, Field(traceKey, traceID))
 }

 spanID := spanIdFromContext(l.ctx)
 if len(spanID) > 0 {
  logFields = append(logFields, Field(spanKey, spanID))
 }

 val := l.ctx.Value(fieldsContextKey)
 if val != nil {
  if arr, ok := val.([]LogField); ok {
   logFields = append(logFields, arr...)
  }
 }

 return logFields
}

if len(c.ServiceName) > 0 {
 AddGlobalFields(Field("serviceName", c.ServiceName))
}

func SetUp(c LogConf) (err error) {
 // Just ignore the subsequent SetUp calls.
 // Because multiple services in one process might call SetUp respectively.
 // Need to wait for the first caller to complete the execution.
 setupOnce.Do(func() {
  if len(c.ServiceName) > 0 {
   AddGlobalFields(Field("serviceName", c.ServiceName))
  }

  setupLogLevel(c)

  if len(c.TimeFormat) > 0 {
   timeFormat = c.TimeFormat
  }

  switch c.Encoding {
  case plainEncoding:
   atomic.StoreUint32(&encoding, plainEncodingType)
  default:
   atomic.StoreUint32(&encoding, jsonEncodingType)
  }

  switch c.Mode {
  case fileMode:
   err = setupWithFiles(c)
  case volumeMode:
   err = setupWithVolume(c)
  default:
   setupWithConsole()
  }
 })

 return
}

// AddGlobalFields adds fields to every log entry.
func AddGlobalFields(fields ...LogField) {
 globalFields.Lock()
 globalFields.fields = append(globalFields.fields, fields...)
 globalFields.Unlock()
}

func output(writer io.Writer, level string, val interface{}, fields ...LogField) {
 existingFields := make(map[string]struct{}, len(fields))
 for _, field := range fields {
  existingFields[field.Key] = struct{}{}
 }
 for _, field := range globalFieldsSnapshot() {
  if _, ok := existingFields[field.Key]; !ok {
   fields = append(fields, field)
  }
 }

 switch atomic.LoadUint32(&encoding) {
 case plainEncodingType:
  writePlainAny(writer, level, val, buildFields(fields...)...)
 default:
  entry := make(logEntry)
  for _, field := range fields {
   entry[field.Key] = field.Value
  }
  entry[timestampKey] = getTimestamp()
  entry[levelKey] = level
  entry[contentKey] = val
  writeJson(writer, entry)
 }
}

func TestOutputIncludesGlobalAndPerCallFields(t *testing.T) {
 oldFields := globalFieldsSnapshot()
 globalFields.Lock()
 globalFields.fields = nil
 globalFields.Unlock()
 defer func() {
  globalFields.Lock()
  globalFields.fields = oldFields
  globalFields.Unlock()
 }()
 AddGlobalFields(Field("serviceName", "billing"))

 oldEncoding := atomic.LoadUint32(&encoding)
 defer atomic.StoreUint32(&encoding, oldEncoding)
 for _, test := range []struct {
  name string
  encoding uint32
 }{
  {name: "json", encoding: jsonEncodingType},
  {name: "plain", encoding: plainEncodingType},
 } {
  t.Run(test.name, func(t *testing.T) {
   atomic.StoreUint32(&encoding, test.encoding)
   var buf bytes.Buffer
   output(&buf, levelInfo, "hello", Field("requestId", "req-1"))

   if test.encoding == jsonEncodingType {
    var entry map[string]interface{}
    if err := json.Unmarshal(buf.Bytes(), &entry); err != nil {
     t.Fatal(err)
    }
    assert.Equal(t, "hello", entry[contentKey])
    assert.Equal(t, "billing", entry["serviceName"])
    assert.Equal(t, "req-1", entry["requestId"])
    return
   }

   assert.Contains(t, buf.String(), "hello")
   assert.Contains(t, buf.String(), "serviceName=billing")
   assert.Contains(t, buf.String(), "requestId=req-1")
  })
 }
}

