}

func TestOutputIncludesGlobalAndPerCallFields(t *testing.T) {
 oldFields := globalFieldsSnapshot()
 globalFields.Lock()
 globalFields.fields = nil
 globalFields.Unlock()
 defer func() {
  globalFields.Lock()
  globalFields.fields = oldFields
  globalFields.Unlock()
 }()
 AddGlobalFields(Field("serviceName", "billing"))
 AddGlobalFields(Field("region", "eu"))

